CREATE TEMP TABLE g AS SELECT m.*, s.id AS src_id, d.id AS dst_id FROM mg m JOIN files s ON s.full_code = m.src LEFT JOIN files d ON d.full_code = m.dst;
DO $$ BEGIN
  IF (SELECT count(*) FROM g) <> (SELECT count(*) FROM mg) THEN RAISE EXCEPTION 'glued source missing'; END IF;
  IF EXISTS (SELECT 1 FROM g WHERE action = 'delete-into-existing' AND dst_id IS NULL) THEN RAISE EXCEPTION 'merge target missing'; END IF;
  IF EXISTS (SELECT 1 FROM g WHERE action = 'rename' AND dst_id IS NOT NULL) THEN RAISE EXCEPTION 'rename target exists'; END IF;
END $$;
-- move relations of duplicates onto the real file
DELETE FROM online_copies oc USING g WHERE oc.file_id = g.src_id AND g.dst_id IS NOT NULL AND EXISTS (SELECT 1 FROM online_copies d WHERE d.file_id = g.dst_id AND d.resource_id = oc.resource_id AND d.url = oc.url AND d.parsed = oc.parsed);
UPDATE online_copies oc SET file_id = g.dst_id FROM g WHERE oc.file_id = g.src_id AND g.dst_id IS NOT NULL;
INSERT INTO file_authors (file_id, author_id) SELECT g.dst_id, fa.author_id FROM file_authors fa JOIN g ON fa.file_id = g.src_id WHERE g.dst_id IS NOT NULL ON CONFLICT DO NOTHING;
DELETE FROM file_authors fa USING g WHERE fa.file_id = g.src_id AND g.dst_id IS NOT NULL;
INSERT INTO file_locations (lat, lng, radius_m, file_id) SELECT l.lat, l.lng, l.radius_m, g.dst_id FROM file_locations l JOIN g ON l.file_id = g.src_id WHERE g.dst_id IS NOT NULL ON CONFLICT DO NOTHING;
UPDATE file_actions x SET file_id = g.dst_id FROM g WHERE x.file_id = g.src_id AND g.dst_id IS NOT NULL;
-- bare targets (451-1-2, 260-1-48) take title/tags/years from the glued duplicate
UPDATE files d SET title = CASE WHEN coalesce(d.title,'') = '' THEN s.title ELSE d.title END, tags = CASE WHEN cardinality(d.tags) = 0 THEN s.tags ELSE d.tags END FROM g JOIN files s ON s.id = g.src_id WHERE d.id = g.dst_id;
INSERT INTO file_years (file_id, start_year, end_year) SELECT g.dst_id, y.start_year, y.end_year FROM file_years y JOIN g ON y.file_id = g.src_id WHERE g.dst_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM file_years d WHERE d.file_id = g.dst_id) ON CONFLICT DO NOTHING;
DELETE FROM files f USING g WHERE f.id = g.src_id AND g.dst_id IS NOT NULL;
-- renames: real code, inventory 1 of the fond, full_code
UPDATE files f SET code = split_part(g.dst, '-', 4), full_code = g.dst,
  inventory_id = (SELECT i.id FROM inventories i JOIN fonds fo ON fo.id = i.fond_id JOIN dadoo_archive a ON a.id = fo.archive_id WHERE fo.code = split_part(g.dst, '-', 2) AND i.code = split_part(g.dst, '-', 3))
FROM g WHERE f.id = g.src_id AND g.dst_id IS NULL;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM files f JOIN g ON f.id = g.src_id WHERE f.inventory_id IS NULL) THEN RAISE EXCEPTION 'rename: inventory 1 missing'; END IF; END $$;
-- phantom inventories (оп. 1 + page number), now empty
CREATE TEMP TABLE gi(fond text, inv text); INSERT INTO gi VALUES ('191','178'),('193','5'),('193','180'),('212','86'),('226','14'),('238','187'),('260','156'),('285','107'),('307','110'),('308','111'),('312','114'),('343','120'),('355','121'),('423','140'),('436','146');
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM inventories i JOIN fonds fo ON fo.id = i.fond_id JOIN dadoo_archive a ON a.id = fo.archive_id JOIN gi ON gi.fond = fo.code AND gi.inv = i.code
             WHERE EXISTS (SELECT 1 FROM files WHERE inventory_id = i.id) OR EXISTS (SELECT 1 FROM online_copies WHERE inventory_id = i.id) OR EXISTS (SELECT 1 FROM inventory_actions WHERE inventory_id = i.id))
  THEN RAISE EXCEPTION 'phantom inventory not empty'; END IF; END $$;
DELETE FROM inventories i USING fonds fo, dadoo_archive a, gi WHERE i.fond_id = fo.id AND fo.archive_id = a.id AND gi.fond = fo.code AND gi.inv = i.code;

-- D. справи present in the catalog but missing in the DB
INSERT INTO inventories (code, fond_id) SELECT '1', fo.id FROM fonds fo JOIN dadoo_archive a ON a.id = fo.archive_id WHERE fo.code = '121' AND NOT EXISTS (SELECT 1 FROM inventories i WHERE i.fond_id = fo.id AND i.code = '1');
