INSERT INTO fond_years (fond_id, start_year, end_year) SELECT fo.id, fy.s, fy.e FROM fy JOIN fonds fo ON fo.code = fy.fond JOIN dadoo_archive a ON a.id = fo.archive_id WHERE NOT EXISTS (SELECT 1 FROM fond_years y WHERE y.fond_id = fo.id) ON CONFLICT DO NOTHING;

-- B. bare files: title / tags / years from the catalog (only where empty)
CREATE TEMP TABLE bf(full_code text, title text, tags text[], years text);
